Được anh. Em làm luôn cho anh bản **game Rắn Săn Mồi hoàn chỉnh bằng HTML + CSS + JavaScript**, chỉ cần lưu thành `index.html` rồi mở trình duyệt là chơi được.

```html
<!DOCTYPE html>
<html lang="vi">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Snake Game</title>

  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      background:
        radial-gradient(circle at top, #1b2735 0%, #090a0f 70%);
      font-family: Arial, Helvetica, sans-serif;
      color: white;
      overflow: hidden;
    }

    .game-wrapper {
      width: min(92vw, 520px);
      padding: 22px;
      border-radius: 26px;
      background: rgba(255, 255, 255, 0.07);
      border: 1px solid rgba(255, 255, 255, 0.12);
      box-shadow:
        0 25px 80px rgba(0, 0, 0, 0.55),
        inset 0 1px 0 rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(16px);
    }

    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 18px;
    }

    .title-box h1 {
      font-size: 28px;
      line-height: 1;
      margin-bottom: 6px;
    }

    .title-box p {
      color: #9ca3af;
      font-size: 13px;
    }

    .score-box {
      display: flex;
      gap: 8px;
    }

    .score-card {
      min-width: 70px;
      background: rgba(255, 255, 255, 0.07);
      border: 1px solid rgba(255, 255, 255, 0.09);
      padding: 9px 12px;
      border-radius: 14px;
      text-align: center;
    }

    .score-card span {
      display: block;
      color: #8b95a7;
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      margin-bottom: 3px;
    }

    .score-card strong {
      font-size: 20px;
      color: #fff;
    }

    .game-container {
      position: relative;
      width: 100%;
      aspect-ratio: 1 / 1;
      border-radius: 20px;
      overflow: hidden;
      background: #0e141c;
      border: 1px solid rgba(255, 255, 255, 0.1);
      box-shadow:
        inset 0 0 40px rgba(0, 0, 0, 0.4),
        0 10px 35px rgba(0, 0, 0, 0.3);
    }

    canvas {
      width: 100%;
      height: 100%;
      display: block;
    }

    .overlay {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(3, 7, 12, 0.68);
      backdrop-filter: blur(6px);
      z-index: 10;
      transition: 0.25s ease;
    }

    .overlay.hidden {
      opacity: 0;
      pointer-events: none;
    }

    .overlay-content {
      text-align: center;
      padding: 20px;
    }

    .overlay-content .icon {
      font-size: 54px;
      margin-bottom: 12px;
    }

    .overlay-content h2 {
      font-size: 30px;
      margin-bottom: 8px;
    }

    .overlay-content p {
      font-size: 14px;
      line-height: 1.6;
      color: #aeb7c5;
      margin-bottom: 20px;
    }

    .start-btn {
      border: 0;
      border-radius: 14px;
      padding: 13px 24px;
      font-size: 15px;
      font-weight: 700;
      cursor: pointer;
      color: #041009;
      background: linear-gradient(135deg, #5cff8d, #22c55e);
      box-shadow: 0 10px 30px rgba(34, 197, 94, 0.26);
      transition: 0.2s ease;
    }

    .start-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 14px 36px rgba(34, 197, 94, 0.35);
    }

    .start-btn:active {
      transform: scale(0.97);
    }

    .controls {
      margin-top: 18px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
    }

    .tips {
      color: #8e98a8;
      font-size: 12px;
      line-height: 1.5;
    }

    .key-group {
      display: grid;
      grid-template-columns: repeat(3, 34px);
      grid-template-rows: repeat(2, 34px);
      gap: 5px;
    }

    .key {
      width: 34px;
      height: 34px;
      border-radius: 9px;
      background: rgba(255, 255, 255, 0.06);
      border: 1px solid rgba(255, 255, 255, 0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      color: #dbe1ea;
      font-size: 14px;
      box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.25);
    }

    .up {
      grid-column: 2;
    }

    .left {
      grid-column: 1;
      grid-row: 2;
    }

    .down {
      grid-column: 2;
      grid-row: 2;
    }

    .right {
      grid-column: 3;
      grid-row: 2;
    }

    .mobile-controls {
      display: none;
      margin-top: 20px;
      justify-content: center;
    }

    .mobile-grid {
      display: grid;
      grid-template-columns: repeat(3, 60px);
      grid-template-rows: repeat(2, 60px);
      gap: 8px;
    }

    .mobile-btn {
      border: none;
      color: white;
      font-size: 22px;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.1);
      cursor: pointer;
      user-select: none;
      touch-action: manipulation;
    }

    .mobile-btn:active {
      background: rgba(92, 255, 141, 0.2);
      transform: scale(0.95);
    }

    @media (max-width: 600px) {
      body {
        align-items: flex-start;
        padding: 16px 0;
        overflow-y: auto;
      }

      .game-wrapper {
        padding: 15px;
        border-radius: 22px;
      }

      .title-box h1 {
        font-size: 22px;
      }

      .title-box p {
        display: none;
      }

      .score-card {
        min-width: 60px;
        padding: 7px 8px;
      }

      .score-card strong {
        font-size: 17px;
      }

      .controls {
        display: none;
      }

      .mobile-controls {
        display: flex;
      }
    }
  </style>
</head>

<body>

  <div class="game-wrapper">

    <div class="header">
      <div class="title-box">
        <h1>🐍 Snake</h1>
        <p>Ăn thức ăn và cố gắng sống lâu nhất có thể</p>
      </div>

      <div class="score-box">
        <div class="score-card">
          <span>Điểm</span>
          <strong id="score">0</strong>
        </div>

        <div class="score-card">
          <span>Kỷ lục</span>
          <strong id="highScore">0</strong>
        </div>
      </div>
    </div>

    <div class="game-container">

      <canvas id="gameCanvas"></canvas>

      <div class="overlay" id="overlay">
        <div class="overlay-content">
          <div class="icon" id="overlayIcon">🐍</div>
          <h2 id="overlayTitle">Snake Game</h2>
          <p id="overlayText">
            Sử dụng ↑ ↓ ← → hoặc WASD<br>
            để điều khiển rắn.
          </p>
          <button class="start-btn" id="startBtn">
            Bắt đầu chơi
          </button>
        </div>
      </div>

    </div>

    <div class="controls">
      <div class="tips">
        Điều khiển bằng <b>WASD</b> hoặc <b>phím mũi tên</b><br>
        Nhấn <b>Space</b> để tạm dừng.
      </div>

      <div class="key-group">
        <div class="key up">↑</div>
        <div class="key left">←</div>
        <div class="key down">↓</div>
        <div class="key right">→</div>
      </div>
    </div>

    <div class="mobile-controls">
      <div class="mobile-grid">
        <button class="mobile-btn up" data-direction="up">↑</button>
        <button class="mobile-btn left" data-direction="left">←</button>
        <button class="mobile-btn down" data-direction="down">↓</button>
        <button class="mobile-btn right" data-direction="right">→</button>
      </div>
    </div>

  </div>

  <script>
    const canvas = document.getElementById("gameCanvas");
    const ctx = canvas.getContext("2d");

    const scoreElement = document.getElementById("score");
    const highScoreElement = document.getElementById("highScore");

    const overlay = document.getElementById("overlay");
    const overlayTitle = document.getElementById("overlayTitle");
    const overlayText = document.getElementById("overlayText");
    const overlayIcon = document.getElementById("overlayIcon");
    const startBtn = document.getElementById("startBtn");

    const GRID_SIZE = 20;

    let cellSize;
    let snake;
    let food;
    let direction;
    let nextDirection;
    let score;
    let highScore;
    let gameLoop;
    let speed;
    let isRunning = false;
    let isPaused = false;

    function resizeCanvas() {
      const container = canvas.parentElement;

      canvas.width = container.clientWidth;
      canvas.height = container.clientHeight;

      cellSize = canvas.width / GRID_SIZE;

      draw();
    }

    window.addEventListener("resize", resizeCanvas);

    function initializeGame() {
      snake = [
        { x: 10, y: 10 },
        { x: 9, y: 10 },
        { x: 8, y: 10 }
      ];

      direction = { x: 1, y: 0 };
      nextDirection = { x: 1, y: 0 };

      score = 0;
      speed = 130;

      scoreElement.textContent = score;

      generateFood();
      draw();
    }

    function generateFood() {
      let position;

      do {
        position = {
          x: Math.floor(Math.random() * GRID_SIZE),
          y: Math.floor(Math.random() * GRID_SIZE)
        };
      } while (
        snake &&
        snake.some(
          segment =>
            segment.x === position.x &&
            segment.y === position.y
        )
      );

      food = position;
    }

    function startGame() {
      clearInterval(gameLoop);

      initializeGame();

      isRunning = true;
      isPaused = false;

      overlay.classList.add("hidden");

      startLoop();
    }

    function startLoop() {
      clearInterval(gameLoop);

      gameLoop = setInterval(update, speed);
    }

    function update() {
      if (!isRunning || isPaused) return;

      direction = nextDirection;

      const head = {
        x: snake[0].x + direction.x,
        y: snake[0].y + direction.y
      };

      if (
        head.x < 0 ||
        head.x >= GRID_SIZE ||
        head.y < 0 ||
        head.y >= GRID_SIZE
      ) {
        gameOver();
        return;
      }

      const hitSelf = snake.some(
        segment =>
          segment.x === head.x &&
          segment.y === head.y
      );

      if (hitSelf) {
        gameOver();
        return;
      }

      snake.unshift(head);

      if (
        head.x === food.x &&
        head.y === food.y
      ) {
        score++;

        scoreElement.textContent = score;

        if (score > highScore) {
          highScore = score;
          localStorage.setItem("snakeHighScore", highScore);
          highScoreElement.textContent = highScore;
        }

        generateFood();

        if (score % 5 === 0 && speed > 60) {
          speed -= 8;
          startLoop();
        }
      } else {
        snake.pop();
      }

      draw();
    }

    function drawGrid() {
      ctx.strokeStyle = "rgba(255,255,255,0.035)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= GRID_SIZE; i++) {
        const position = i * cellSize;

        ctx.beginPath();
        ctx.moveTo(position, 0);
        ctx.lineTo(position, canvas.height);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0, position);
        ctx.lineTo(canvas.width, position);
        ctx.stroke();
      }
    }

    function draw() {
      if (!canvas.width) return;

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const gradient = ctx.createLinearGradient(
        0,
        0,
        canvas.width,
        canvas.height
      );

      gradient.addColorStop(0, "#101923");
      gradient.addColorStop(1, "#091017");

      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      drawGrid();

      if (!snake) return;

      drawFood();
      drawSnake();
    }

    function drawFood() {
      if (!food) return;

      const centerX = food.x * cellSize + cellSize / 2;
      const centerY = food.y * cellSize + cellSize / 2;

      ctx.shadowColor = "#ff4757";
      ctx.shadowBlur = 18;

      ctx.fillStyle = "#ff4757";

      ctx.beginPath();
      ctx.arc(
        centerX,
        centerY,
        cellSize * 0.31,
        0,
        Math.PI * 2
      );
      ctx.fill();

      ctx.shadowBlur = 0;

      ctx.fillStyle = "#ff7b87";

      ctx.beginPath();
      ctx.arc(
        centerX - cellSize * 0.1,
        centerY - cellSize * 0.1,
        cellSize * 0.07,
        0,
        Math.PI * 2
      );
      ctx.fill();
    }

    function drawSnake() {
      snake.forEach((segment, index) => {

        const x = segment.x * cellSize;
        const y = segment.y * cellSize;

        const padding = cellSize * 0.08;

        const green =
          Math.max(120, 255 - index * 4);

        ctx.fillStyle =
          index === 0
            ? "#61ff8f"
            : `rgb(45, ${green}, 105)`;

        if (index === 0) {
          ctx.shadowColor = "#39ff78";
          ctx.shadowBlur = 12;
        }

        roundedRect(
          x + padding,
          y + padding,
          cellSize - padding * 2,
          cellSize - padding * 2,
          cellSize * 0.28
        );

        ctx.fill();
        ctx.shadowBlur = 0;

        if (index === 0) {
          drawEyes(segment);
        }
      });
    }

    function roundedRect(x, y, width, height, radius) {
      ctx.beginPath();

      ctx.roundRect(
        x,
        y,
        width,
        height,
        radius
      );
    }

    function drawEyes(head) {
      const x = head.x * cellSize;
      const y = head.y * cellSize;

      ctx.fillStyle = "#06120a";

      const eyeSize = cellSize * 0.08;

      let eye1;
      let eye2;

      if (direction.x === 1) {
        eye1 = {
          x: x + cellSize * 0.7,
          y: y + cellSize * 0.32
        };

        eye2 = {
          x: x + cellSize * 0.7,
          y: y + cellSize * 0.68
        };
      }

      else if (direction.x === -1) {
        eye1 = {
          x: x + cellSize * 0.3,
          y: y + cellSize * 0.32
        };

        eye2 = {
          x: x + cellSize * 0.3,
          y: y + cellSize * 0.68
        };
      }

      else if (direction.y === -1) {
        eye1 = {
          x: x + cellSize * 0.32,
          y: y + cellSize * 0.3
        };

        eye2 = {
          x: x + cellSize * 0.68,
          y: y + cellSize * 0.3
        };
      }

      else {
        eye1 = {
          x: x + cellSize * 0.32,
          y: y + cellSize * 0.7
        };

        eye2 = {
          x: x + cellSize * 0.68,
          y: y + cellSize * 0.7
        };
      }

      ctx.beginPath();
      ctx.arc(
        eye1.x,
        eye1.y,
        eyeSize,
        0,
        Math.PI * 2
      );
      ctx.fill();

      ctx.beginPath();
      ctx.arc(
        eye2.x,
        eye2.y,
        eyeSize,
        0,
        Math.PI * 2
      );
      ctx.fill();
    }

    function gameOver() {
      isRunning = false;

      clearInterval(gameLoop);

      overlayIcon.textContent = "💀";
      overlayTitle.textContent = "Game Over";

      overlayText.innerHTML =
        `Điểm của anh: <b>${score}</b><br>` +
        `Kỷ lục: <b>${highScore}</b>`;

      startBtn.textContent = "Chơi lại";

      overlay.classList.remove("hidden");
    }

    function togglePause() {
      if (!isRunning) return;

      isPaused = !isPaused;

      if (isPaused) {
        overlayIcon.textContent = "⏸️";
        overlayTitle.textContent = "Tạm dừng";

        overlayText.innerHTML =
          "Nhấn <b>Space</b> để tiếp tục.";

        startBtn.style.display = "none";

        overlay.classList.remove("hidden");
      } else {
        overlay.classList.add("hidden");

        startBtn.style.display = "inline-block";
      }
    }

    function changeDirection(newDirection) {
      if (
        direction.x + newDirection.x === 0 &&
        direction.y + newDirection.y === 0
      ) {
        return;
      }

      nextDirection = newDirection;
    }

    document.addEventListener("keydown", event => {

      const key = event.key.toLowerCase();

      if (
        ["arrowup", "arrowdown", "arrowleft", "arrowright", " "]
        .includes(key)
      ) {
        event.preventDefault();
      }

      if (key === "arrowup" || key === "w") {
        changeDirection({ x: 0, y: -1 });
      }

      if (key === "arrowdown" || key === "s") {
        changeDirection({ x: 0, y: 1 });
      }

      if (key === "arrowleft" || key === "a") {
        changeDirection({ x: -1, y: 0 });
      }

      if (key === "arrowright" || key === "d") {
        changeDirection({ x: 1, y: 0 });
      }

      if (key === " ") {
        togglePause();
      }
    });

    document
      .querySelectorAll(".mobile-btn")
      .forEach(button => {

        button.addEventListener("pointerdown", () => {

          const directionName =
            button.dataset.direction;

          const directions = {
            up: { x: 0, y: -1 },
            down: { x: 0, y: 1 },
            left: { x: -1, y: 0 },
            right: { x: 1, y: 0 }
          };

          changeDirection(
            directions[directionName]
          );
        });

      });

    startBtn.addEventListener("click", () => {

      startBtn.style.display = "inline-block";
      startGame();

    });

    highScore =
      Number(
        localStorage.getItem("snakeHighScore")
      ) || 0;

    highScoreElement.textContent = highScore;

    resizeCanvas();
    initializeGame();
  </script>

</body>
</html>
```

### Game này có sẵn

- 🐍 Rắn di chuyển mượt
- 🍎 Thức ăn ngẫu nhiên
- 💀 Va tường hoặc cắn vào thân sẽ thua
- 🏆 Lưu **kỷ lục cao nhất** bằng `localStorage`
- ⚡ Cứ mỗi **5 điểm sẽ tăng tốc**
- ⏸️ Nhấn `Space` để pause
- 🎮 Điều khiển bằng `WASD` hoặc phím mũi tên
- 📱 Có nút điều khiển trên điện thoại
- ✨ Giao diện dark/glass hiện đại
- 🐍 Đầu rắn có mắt xoay theo hướng di chuyển
- 🍎 Hiệu ứng glow cho thức ăn
- Responsive desktop/mobile

